35	import org.springframework.samples.petclinic.rest.controller.HouseholdAssigner;
36	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateValidator;
37	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
38	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
