60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    private final OwnerFieldsValidator ownerFieldsValidator;
78	
79	    private final TelephoneNormalizer telephoneNormalizer;
80	
81	    private final EmailNormalizer emailNormalizer;
82	
83	    private final AddressNormalizer addressNormalizer;
84	
85	    private final HouseholdDuplicateValidator householdDuplicateValidator;
86	
87	    private final HouseholdAssigner householdAssigner;
88	
89	    private final CityCapacityValidator cityCapacityValidator;
90	
91	    private final DailyRegistrationLimitValidator dailyRegistrationLimitValidator;
92	
93	    private final BusinessDayAdjuster businessDayAdjuster;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 OwnerFieldsValidator ownerFieldsValidator,
100	                                 TelephoneNormalizer telephoneNormalizer,
101	                                 EmailNormalizer emailNormalizer,
102	                                 AddressNormalizer addressNormalizer,
103	                                 HouseholdDuplicateValidator householdDuplicateValidator,
104	                                 HouseholdAssigner householdAssigner,
105	                                 CityCapacityValidator cityCapacityValidator,
106	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
107	                                 BusinessDayAdjuster businessDayAdjuster) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.ownerFieldsValidator = ownerFieldsValidator;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.emailNormalizer = emailNormalizer;
115	        this.addressNormalizer = addressNormalizer;
116	        this.householdDuplicateValidator = householdDuplicateValidator;
117	        this.householdAssigner = householdAssigner;
118	        this.cityCapacityValidator = cityCapacityValidator;
119	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
120	        this.businessDayAdjuster = businessDayAdjuster;
121	    }
122	
123	    /**
124	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
125	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
126	     */
127	    @InitBinder("ownerFieldsDto")
128	    void initOwnerFieldsBinder(WebDataBinder binder) {
129	        binder.addValidators(ownerFieldsValidator);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
160	        HttpHeaders headers = new HttpHeaders();
161	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
162	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
163	        LocalDate registrationDate = owner.getRegistrationDate() != null
164	            ? owner.getRegistrationDate() : LocalDate.now();
165	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
166	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
167	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
168	            throw new DuplicateTelephoneException(telephone);
169	        }
170	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
171	        cityCapacityValidator.validate(owner);
172	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            householdAssigner.assignSharedHousehold(owner);
174	        } else {
175	            householdDuplicateValidator.validate(owner);
176	        }
177	        owner.setTelephone(telephone);
178	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
179	        this.clinicService.saveOwner(owner);
180	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
181	        headers.setLocation(UriComponentsBuilder.newInstance()
182	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
183	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        currentOwner.setAddress(ownerFieldsDto.getAddress());
194	        currentOwner.setCity(ownerFieldsDto.getCity());
195	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
196	        currentOwner.setLastName(ownerFieldsDto.getLastName());
197	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
198	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
199	        this.clinicService.saveOwner(currentOwner);
200	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        this.clinicService.deleteOwner(owner);
212	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        Pet pet = petMapper.toPet(petFieldsDto);
224	        owner.setId(ownerId);
225	        pet.setOwner(owner);
226	        pet.getType().setName(null);
227	        this.clinicService.savePet(pet);
228	        PetDto petDto = petMapper.toPetDto(pet);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
230	            .buildAndExpand(pet.getId()).toUri());
231	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner != null) {
239	            Pet currentPet = this.clinicService.findPetById(petId);
240	            if (currentPet != null) {
241	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
242	                currentPet.setName(petFieldsDto.getName());
243	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
244	                this.clinicService.savePet(currentPet);
245	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
254	        HttpHeaders headers = new HttpHeaders();
255	        Visit visit = visitMapper.toVisit(visitFieldsDto);
256	        Pet pet = new Pet();
257	        pet.setId(petId);
258	        visit.setPet(pet);
259	        this.clinicService.saveVisit(visit);
260	        VisitDto visitDto = visitMapper.toVisitDto(visit);
261	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
262	            .buildAndExpand(visit.getId()).toUri());
263	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
264	    }
265	
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner != null) {
272	            Pet pet = owner.getPet(petId);
273	            if (pet != null) {
274	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	}
