24	/**
25	 * Normalizes a raw owner address into its canonical, storable form.
26	 * <p>
27	 * Surrounding whitespace is trimmed, internal whitespace runs collapse to a single space and the
28	 * value is upper-cased. Common street-type abbreviations are then expanded to their full words
29	 * ({@code ST} &rarr; {@code STREET}, {@code RD} &rarr; {@code ROAD}, {@code AVE} &rarr;
30	 * {@code AVENUE}). A {@code null} or blank input yields an empty string, so the required-field
31	 * check rejects an address that is blank once normalized.
32	 */
33	@Component
34	public class AddressNormalizer {
35	
36	    /** Street-type abbreviations expanded to their full words, keyed by the upper-cased token. */
37	    private static final Map<String, String> ABBREVIATIONS = Map.of(
38	        "ST", "STREET",
39	        "RD", "ROAD",
40	        "AVE", "AVENUE");
41	
42	    /**
43	     * Canonicalize {@code rawAddress} for storage and comparison.
44	     *
45	     * @param rawAddress the address as supplied by the client (may be {@code null} or blank)
46	     * @return the trimmed, whitespace-collapsed, upper-cased address with common street-type
47	     *     abbreviations expanded, or an empty string when the input is {@code null} or blank
48	     */
49	    public String normalize(String rawAddress) {
50	        if (rawAddress == null) {
51	            return "";
52	        }
53	        String cleaned = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
54	        if (cleaned.isEmpty()) {
55	            return "";
56	        }
57	        String[] tokens = cleaned.split(" ");
58	        for (int i = 0; i < tokens.length; i++) {
59	            tokens[i] = ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]);
60	        }
61	        return String.join(" ", tokens);
62	    }
63	}
